#version 450
layout(location=0) in vec4 pica_primary_color;
layout(location=1) in vec2 pica_texcoord0;
layout(location=2) in vec2 pica_texcoord1;
layout(location=3) in vec2 pica_texcoord2;
layout(location=4) in float pica_texcoord0_w;
layout(location=5) in vec4 pica_normquat;
layout(location=6) in vec3 pica_view;
layout(set=0,binding=1) uniform sampler2D pica_texture0;
layout(set=0,binding=2) uniform sampler2D pica_texture1;
layout(set=0,binding=3) uniform sampler2D pica_texture2;
layout(set=0,binding=4,std140) uniform PicaFragmentUniforms {
    vec4 tev_constants[6];
    vec4 combiner_buffer_color;
    int alpha_reference;
    float depth_scale;
    float depth_offset;
    int w_buffering;
    vec4 fog_color;
    vec4 fog_lut[64];
    vec4 texture_lod_bias;
    vec4 lighting_specular0[8];
    vec4 lighting_specular1[8];
    vec4 lighting_diffuse[8];
    vec4 lighting_ambient[8];
    vec4 lighting_position[8];
    vec4 lighting_spot_direction[8];
    vec4 lighting_attenuation[8];
    vec4 lighting_global_ambient;
    int shadow_texture_bias;
    int shadow_orthographic;
    float shadow_bias_constant;
    float shadow_bias_linear;
} fragment_uniforms;
layout(location=0) out vec4 pica_color;
vec3 byteround3(vec3 value) { return floor(value * 255.0 + 0.5) / 255.0; }
float byteround1(float value) { return floor(value * 255.0 + 0.5) / 255.0; }
float pica_texture_lod(vec2 coord, vec2 size) {
    vec2 scaled = coord * size;
    vec2 delta = max(abs(dFdx(scaled)), abs(dFdy(scaled)));
    return log2(max(delta.x, delta.y));
}
vec4 pica_sample_texture0(vec2 coord) {
    float lod = pica_texture_lod(coord, vec2(textureSize(pica_texture0, 0)));
    return textureLod(pica_texture0, coord, lod + fragment_uniforms.texture_lod_bias[0]);
}
vec4 pica_sample_texture1(vec2 coord) {
    float lod = pica_texture_lod(coord, vec2(textureSize(pica_texture1, 0)));
    return textureLod(pica_texture1, coord, lod + fragment_uniforms.texture_lod_bias[1]);
}
vec4 pica_sample_texture2(vec2 coord) {
    float lod = pica_texture_lod(coord, vec2(textureSize(pica_texture2, 0)));
    return textureLod(pica_texture2, coord, lod + fragment_uniforms.texture_lod_bias[2]);
}

#define OOT3D_TOON_BAND_SPAN 3.000000
#define OOT3D_TOON_SOFTNESS 0.228000
#define OOT3D_TOON_SATURATION 1.090000
#define OOT3D_TOON_HAS_VERTEX_LIGHT 1.0
#define OOT3D_TOON_SHADOW_TINT vec3(0.480000, 0.560000, 0.720000)
#define OOT3D_TOON_SHADOW_STRENGTH 1.000000
#define OOT3D_TOON_RIM_STRENGTH 0.340000
#define OOT3D_TOON_RIM_WIDTH 3.170000
#define OOT3D_TOON_RIM_TINT vec3(1.000000, 0.930000, 0.720000)

vec3 oot3d_toon_rotate_z(vec4 q) {
    float qlen = dot(q, q);
    if (qlen < 0.000001) return vec3(0.0, 0.0, 1.0);
    q *= inversesqrt(qlen);
    return vec3(2.0 * (q.x * q.z + q.w * q.y),
                2.0 * (q.y * q.z - q.w * q.x),
                1.0 - 2.0 * (q.x * q.x + q.y * q.y));
}

float oot3d_toon_band_luminance(float guide) {
    float scaled = guide * OOT3D_TOON_BAND_SPAN;
    float lowerBand = floor(scaled);
    float transition = smoothstep(0.5 - OOT3D_TOON_SOFTNESS,
                                  0.5 + OOT3D_TOON_SOFTNESS,
                                  fract(scaled));
    return (lowerBand + transition) / OOT3D_TOON_BAND_SPAN;
}


vec3 oot3d_apply_toon(vec3 sourceColor) {
    const vec3 lumaWeights = vec3(0.2126, 0.7152, 0.0722);
    // Quantize the interpolated PICA lighting/color contribution, never the
    // post-TEV texel. This preserves albedo gradients and texture detail.
    float lightingGuide = clamp(dot(pica_primary_color.rgb, lumaWeights), 0.0, 1.0);
    float bandLuminance = oot3d_toon_band_luminance(lightingGuide);
    float lightingScale = clamp(bandLuminance / max(lightingGuide, 0.05),
                                0.0, 2.0);
    lightingScale = mix(1.0, lightingScale, OOT3D_TOON_HAS_VERTEX_LIGHT);
    vec3 banded = sourceColor * lightingScale;
    float bandedLuma = dot(banded, lumaWeights);
    banded = mix(vec3(bandedLuma), banded, OOT3D_TOON_SATURATION);
    float shadowMask = (1.0 - smoothstep(0.0, 0.55, bandLuminance)) *
                       OOT3D_TOON_HAS_VERTEX_LIGHT;
    banded = mix(banded, banded * OOT3D_TOON_SHADOW_TINT,
                 shadowMask * OOT3D_TOON_SHADOW_STRENGTH);
    vec3 normal = normalize(oot3d_toon_rotate_z(pica_normquat));
    vec3 viewDirection = dot(pica_view, pica_view) > 0.000001
        ? normalize(pica_view) : vec3(0.0, 0.0, 1.0);
    float rim = pow(clamp(1.0 - abs(dot(normal, viewDirection)), 0.0, 1.0),
                    OOT3D_TOON_RIM_WIDTH);
    return clamp(banded + OOT3D_TOON_RIM_TINT *
                 (rim * OOT3D_TOON_RIM_STRENGTH), 0.0, 1.0);
}

vec3 oot3d_material_bands(vec3 lighting, bool shadow_tint) {
    const vec3 lumaWeights = vec3(0.2126, 0.7152, 0.0722);
    float guide = clamp(dot(lighting, lumaWeights), 0.0, 1.0);
    float bandLuminance = oot3d_toon_band_luminance(guide);
    vec3 banded = lighting * clamp(bandLuminance / max(guide, 0.05), 0.0, 2.0);
    float bandedLuma = dot(banded, lumaWeights);
    banded = mix(vec3(bandedLuma), banded, OOT3D_TOON_SATURATION);
    if (shadow_tint) {
        float shadowMask = 1.0 - smoothstep(0.0, 0.55, bandLuminance);
        banded = mix(banded, banded * OOT3D_TOON_SHADOW_TINT,
                     shadowMask * OOT3D_TOON_SHADOW_STRENGTH);
    }
    return clamp(banded, 0.0, 1.0);
}

vec3 oot3d_material_rim(vec3 materialNormal) {
    vec3 normal = normalize(materialNormal);
    vec3 viewDirection = dot(pica_view, pica_view) > 0.000001
        ? normalize(pica_view) : vec3(0.0, 0.0, 1.0);
    float rim = pow(clamp(1.0 - abs(dot(normal, viewDirection)), 0.0, 1.0),
                    OOT3D_TOON_RIM_WIDTH);
    return OOT3D_TOON_RIM_TINT * (rim * OOT3D_TOON_RIM_STRENGTH);
}
void main() {
    vec4 rounded_primary_color = vec4(byteround3(pica_primary_color.rgb), byteround1(pica_primary_color.a));
    vec4 primary_fragment_color = vec4(0.0);
    vec4 secondary_fragment_color = vec4(0.0);
    vec4 combiner_buffer = vec4(0.0);
    vec4 next_combiner_buffer = fragment_uniforms.combiner_buffer_color;
    vec4 combiner_output = vec4(0.0);
    // OOT3D_PICA_LIGHTING_EXTENSION_POINT
    vec3 color_output_0 = byteround3(clamp(rounded_primary_color.rgb * pica_sample_texture0(vec2(pica_texcoord0.x, 1.0 - pica_texcoord0.y)).rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_0 = byteround1(clamp(rounded_primary_color.a * pica_sample_texture0(vec2(pica_texcoord0.x, 1.0 - pica_texcoord0.y)).a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_0 * 2.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_0 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_1 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_1 = byteround1(clamp(combiner_output.a * fragment_uniforms.tev_constants[1].a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_1 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_1 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_2 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_2 = byteround1(clamp(combiner_output.a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_2 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_2 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_3 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_3 = byteround1(clamp(combiner_output.a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_3 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_3 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_4 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_4 = byteround1(clamp(combiner_output.a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_4 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_4 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    vec3 color_output_5 = byteround3(clamp(combiner_output.rgb, vec3(0.0), vec3(1.0)));
    float alpha_output_5 = byteround1(clamp(combiner_output.a, 0.0, 1.0));
    combiner_output = vec4(clamp(color_output_5 * 1.0, vec3(0.0), vec3(1.0)), clamp(alpha_output_5 * 1.0, 0.0, 1.0));
    combiner_buffer = next_combiner_buffer;
    int alpha_byte = int(combiner_output.a * 255.0);
    if (alpha_byte <= fragment_uniforms.alpha_reference) discard;
    combiner_output.rgb = oot3d_apply_toon(combiner_output.rgb);
    float pica_z_over_w = -gl_FragCoord.z;
    float pica_depth = pica_z_over_w * fragment_uniforms.depth_scale + fragment_uniforms.depth_offset;
    if (fragment_uniforms.w_buffering != 0) pica_depth /= gl_FragCoord.w;
    float fog_index = pica_depth * 128.0;
    float fog_i = clamp(floor(fog_index), 0.0, 127.0);
    int fog_entry_index = int(fog_i);
    vec4 fog_pair = fragment_uniforms.fog_lut[fog_entry_index >> 1];
    vec2 fog_entry = (fog_entry_index & 1) == 0 ? fog_pair.xy : fog_pair.zw;
    float fog_factor = clamp(fog_entry.x + fog_entry.y * (fog_index - fog_i), 0.0, 1.0);
    combiner_output.rgb = mix(fragment_uniforms.fog_color.rgb, combiner_output.rgb, fog_factor);
    gl_FragDepth = pica_depth;
    pica_color = vec4(byteround3(combiner_output.rgb), byteround1(combiner_output.a));
}

