#define OOT3D_TOON_BAND_SPAN 3.000000
#define OOT3D_TOON_SOFTNESS 0.228000
#define OOT3D_TOON_SATURATION 1.090000
#define OOT3D_TOON_HAS_VERTEX_LIGHT 1.0
#define OOT3D_TOON_SHADOW_TINT vec3(0.480000, 0.560000, 0.720000)
#define OOT3D_TOON_SHADOW_STRENGTH 1.000000
#define OOT3D_TOON_RIM_STRENGTH 0.340000
#define OOT3D_TOON_RIM_WIDTH 3.170000
