    float shadowMask = (1.0 - smoothstep(0.0, 0.55, bandLuminance)) *
                       OOT3D_TOON_HAS_VERTEX_LIGHT;
    banded = mix(banded, banded * OOT3D_TOON_SHADOW_TINT,
                 shadowMask * OOT3D_TOON_SHADOW_STRENGTH);
